CREATE TABLE IF NOT EXISTS address_labels (
        address TEXT PRIMARY KEY,
        label TEXT NOT NULL,
        category TEXT DEFAULT 'general',
        color TEXT DEFAULT '#4f46e5',
        notes TEXT DEFAULT '',
        is_watched INTEGER DEFAULT 0,
        updated_at INTEGER NOT NULL
      );

CREATE TABLE IF NOT EXISTS app_languages (
    code TEXT PRIMARY KEY,
    flag TEXT NOT NULL,
    label TEXT NOT NULL,
    native_name TEXT NOT NULL,
    country TEXT NOT NULL,
    is_default INTEGER DEFAULT 0,
    display_order INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS app_translations (
    lang_code TEXT NOT NULL,
    translation_key TEXT NOT NULL,
    translation_value TEXT NOT NULL,
    updated_at INTEGER,
    PRIMARY KEY (lang_code, translation_key)
);

CREATE TABLE IF NOT EXISTS biomapper_chains (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    short_name TEXT NOT NULL,
    chain_id INTEGER NOT NULL,
    type_key TEXT NOT NULL,
    category TEXT NOT NULL,
    contract_address TEXT NOT NULL,
    explorer_name TEXT NOT NULL,
    explorer_url TEXT NOT NULL,
    status_key TEXT NOT NULL,
    icon_color TEXT NOT NULL,
    generations_supported TEXT NOT NULL,
    sdk_interface TEXT NOT NULL,
    features_json TEXT NOT NULL,
    display_order INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS blocks_with_tx (
        number INTEGER PRIMARY KEY,
        timestamp INTEGER,
        tx_count INTEGER,
        gas_used INTEGER,
        total_fees_hmnd REAL
      , author_id TEXT DEFAULT '');

CREATE TABLE IF NOT EXISTS cross_layer_links (
    substrate_address TEXT NOT NULL,
    evm_address TEXT NOT NULL,
    total_swapped_hmnd REAL DEFAULT 0,
    swap_count INTEGER DEFAULT 0,
    first_swap_block INTEGER,
    last_swap_block INTEGER,
    first_swap_ts INTEGER,
    last_swap_ts INTEGER,
    PRIMARY KEY (substrate_address, evm_address)
  );

CREATE TABLE IF NOT EXISTS evm_method_signatures (
    selector TEXT PRIMARY KEY,
    function_name TEXT NOT NULL,
    signature TEXT NOT NULL,
    category_code TEXT NOT NULL,
    description_key TEXT NOT NULL,
    param_names TEXT DEFAULT '',
    param_types TEXT DEFAULT '',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS hmnd_daily_prices (
    day TEXT PRIMARY KEY,
    price_usd REAL NOT NULL,
    swaps_count INTEGER DEFAULT 0,
    source TEXT DEFAULT 'DEX_SWAP'
  );

CREATE TABLE IF NOT EXISTS query_sandbox_presets (
    id TEXT PRIMARY KEY,
    title_key TEXT NOT NULL,
    description_key TEXT NOT NULL,
    sql_query TEXT NOT NULL,
    display_order INTEGER DEFAULT 0
);

CREATE TABLE IF NOT EXISTS substrate_extrinsics (
        hash TEXT PRIMARY KEY,
        block_number INTEGER,
        timestamp INTEGER,
        pallet TEXT,
        method TEXT,
        signer TEXT,
        target TEXT,
        value_hmnd REAL,
        fee_hmnd REAL,
        status INTEGER,
        details TEXT
      );

CREATE TABLE IF NOT EXISTS sync_state (
        key TEXT PRIMARY KEY,
        value TEXT
      );

CREATE TABLE IF NOT EXISTS system_config (
    config_key TEXT PRIMARY KEY,
    config_value TEXT NOT NULL,
    description TEXT NOT NULL,
    updated_at INTEGER NOT NULL DEFAULT (strftime('%s', 'now'))
);

CREATE TABLE IF NOT EXISTS token_transfers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        tx_hash TEXT,
        block_number INTEGER,
        timestamp INTEGER,
        token_address TEXT,
        token_symbol TEXT,
        from_address TEXT,
        to_address TEXT,
        amount REAL
      );

CREATE TABLE IF NOT EXISTS tokens_cache (
        address TEXT PRIMARY KEY,
        symbol TEXT,
        decimals INTEGER,
        name TEXT
      );

CREATE TABLE IF NOT EXISTS tokens_metadata (
    token_address TEXT PRIMARY KEY,
    symbol TEXT NOT NULL,
    name TEXT NOT NULL,
    category_code TEXT NOT NULL,
    color TEXT NOT NULL,
    decimals INTEGER DEFAULT 18,
    is_curated INTEGER DEFAULT 1
);

CREATE TABLE IF NOT EXISTS transactions (
        hash TEXT PRIMARY KEY,
        block_number INTEGER,
        timestamp INTEGER,
        from_address TEXT,
        to_address TEXT,
        value_wei TEXT,
        value_hmnd REAL,
        gas_used INTEGER,
        effective_gas_price TEXT,
        fee_wei TEXT,
        fee_hmnd REAL,
        status INTEGER
      );

CREATE TABLE IF NOT EXISTS validator_payouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    block_number INTEGER NOT NULL,
    timestamp INTEGER NOT NULL,
    validator_address TEXT NOT NULL,
    amount_hmnd REAL NOT NULL,
    source TEXT DEFAULT 'FeesPot'
);

CREATE TABLE IF NOT EXISTS wallet_balances_cache (
        address TEXT PRIMARY KEY,
        balance_hmnd REAL NOT NULL,
        updated_at INTEGER NOT NULL
      );

CREATE TABLE IF NOT EXISTS wallet_personas (
    id TEXT PRIMARY KEY,
    label_key TEXT NOT NULL,
    desc_key TEXT NOT NULL,
    icon TEXT NOT NULL,
    color TEXT NOT NULL,
    min_balance REAL DEFAULT 0,
    min_volume REAL DEFAULT 0,
    min_txs INTEGER DEFAULT 0,
    is_validator_required INTEGER DEFAULT 0,
    is_bridge_required INTEGER DEFAULT 0
);

