-- -------------------------------------------------------------
-- 3. VIEW DEFINITIONS
-- -------------------------------------------------------------

CREATE VIEW IF NOT EXISTS vw_active_validators AS SELECT cand.address as address, cand.last_seen as last_seen, cand.recent_blocks as recent_blocks FROM (SELECT author_id as address, MAX(timestamp) as last_seen, COUNT(*) as recent_blocks FROM blocks_with_tx WHERE timestamp >= (strftime('%s', 'now') - 2592000) AND author_id > '' GROUP BY author_id UNION ALL SELECT signer as address, MAX(timestamp) as last_seen, 0 as recent_blocks FROM substrate_extrinsics WHERE pallet IN ('bioauth', 'session') AND signer > '' AND timestamp >= (strftime('%s', 'now') - 2592000) GROUP BY signer) cand;

CREATE VIEW IF NOT EXISTS vw_biomapper_chains AS SELECT chain_key as id, name, short_name as shortName, chain_id as chainId, type_key as type, category, contract_address as contractAddress, explorer_name as explorerName, explorer_url as explorerUrl, status_key as status, icon_color as iconColor, generations_supported as generationsSupported, sdk_interface as sdkInterface, features_json FROM biomapper_chains;

CREATE VIEW IF NOT EXISTS vw_feespot_analytics AS SELECT block_number, timestamp, COUNT(*) as recipient_count, ROUND(SUM(amount_hmnd), 2) as total_distributed, ROUND(AVG(amount_hmnd), 2) as sample_per_validator FROM validator_payouts GROUP BY block_number, timestamp;

CREATE VIEW IF NOT EXISTS vw_governance_proposals AS SELECT hash, block_number, timestamp, signer, pallet, method, status FROM substrate_extrinsics WHERE pallet IN ('democracy', 'collective', 'electionsPhragmen');

CREATE VIEW IF NOT EXISTS vw_network_stats AS SELECT (SELECT MAX(number) FROM blocks_with_tx) as latest_block, (SELECT COUNT(*) FROM blocks_with_tx) as total_blocks, ((SELECT COUNT(*) FROM substrate_extrinsics) + (SELECT COUNT(*) FROM transactions)) as total_transactions, (SELECT COUNT(*) FROM transactions) as total_evm_transactions, (SELECT COUNT(*) FROM substrate_extrinsics) as total_substrate_extrinsics, (SELECT COALESCE(SUM(total_fees_hmnd), 0) FROM blocks_with_tx) as total_fees_hmnd;

CREATE VIEW IF NOT EXISTS vw_token_directory AS SELECT t.token_symbol, t.token_address, COUNT(*) as transfer_count, COALESCE(SUM(t.amount), 0) as total_volume, COUNT(DISTINCT t.from_address) as unique_senders, COUNT(DISTINCT t.to_address) as unique_holders, MIN(t.timestamp) as first_seen, MAX(t.timestamp) as last_seen, m.name as meta_name, m.category_code as meta_category, m.color as meta_color FROM token_transfers t LEFT JOIN tokens_metadata m ON LOWER(t.token_address) = LOWER(m.token_address) GROUP BY t.token_address, t.token_symbol;

CREATE VIEW IF NOT EXISTS vw_top_whales AS SELECT b.address as address, b.balance_hmnd as balance, b.layer as layer, COALESCE(l.label, '') as label, COALESCE(l.category, '') as category FROM balances b LEFT JOIN address_labels l ON LOWER(b.address) = LOWER(l.address) WHERE b.balance_hmnd > 0;

