INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'tokenomics_humanode400000000', 'Humanode ağının 400.000.000 HMND sabit toplam arz yapısı, resmi dolaşımdaki likit miktar, kilitli vakıf rezervleri, hak edilmeyi bekleyen airdrop havuzu ve yakma kontratında yok edilen coinler.', 1794521528);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'tokenomics_humanode400000000', 'Official 400,000,000 HMND fixed total supply architecture of Humanode network, verified circulating amount, locked foundation reserves, claimable airdrop pool and coins burned via the burn contract.', 1794521528);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'tokenomics_humanode400000000', 'Offizielle feste Gesamtangebotsarchitektur von 400.000.000 HMND des Humanode-Netzwerks, verifizierte Umlaufmenge, gesperrte Stiftungsreserven, Airdrop-Pool und über den Burn-Vertrag vernichtete Coins.', 1794521528);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'tokenomics_humanode400000000', 'Официальная архитектура фиксированного общего предложения Humanode в 400 000 000 HMND, верифицированное обращение, заблокированные фонды, аирдроп и сожженные в смарт-контракте монеты.', 1794521528);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'tokenomics_humanode400000000', 'Arquitectura de suministro total fijo oficial de 400,000,000 HMND de Humanode, circulante verificado, reservas bloqueadas, airdrop y monedas quemadas mediante el contrato de quema.', 1794521528);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'tokenomics_humanode400000000', 'Humanode 网络的 400,000,000 HMND 官方固定总供应量架构，验证的流通量、锁定的基金会储备、空投池以及通过销毁合约销毁的代币。', 1794521528);
