INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_pohSummary', 'Modelo de consenso igualitario donde nadie obtiene votos adicionales sin importar el capital.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_pohSummary', '人人平等的共识机制，无论质押多少代币，任何人都不会获得额外的投票权或出块权。', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_pohDetails', 'Humanode ağında her validatör tekil bir insana aittir. Zenginlik (PoS) veya saf işlem gücü (PoW) değil, kriptografik olarak kanıtlanmış tekil insan varlığı doğrulama yetkisini belirler.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_pohDetails', 'In Humanode, every validator belongs to a unique human. Cryptographically verified unique human existence determines validation authority.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_pohDetails', 'Im Humanode-Netzwerk gehört jeder Validator einem einzigartigen Menschen. Kryptografisch verifizierte Existenz bestimmt die Autorität.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_pohDetails', 'В Humanode каждый валидатор принадлежит уникальному человеку. Криптографически доказанное присутствие определяет валидацию.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_pohDetails', 'En Humanode, cada validador pertenece a un humano único. La presencia humana criptográficamente probada determina la validación.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_pohDetails', '在 Humanode 网络中，每个验证者都对应一个独立的人类。验证权限由密码学生物证明决定，而非财富 (PoS) 或算力 (PoW)。', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_bioauthTitle', 'Biyometrik Doğrulama & 168 Saat (42 Epoch)', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_bioauthTitle', 'Biometric Verification & 168 Hours (42 Epochs)', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_bioauthTitle', 'Biometrische Verifizierung & 168 Stunden (42 Epochen)', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_bioauthTitle', 'Биометрическая верификация и 168 часов (42 эпохи)', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_bioauthTitle', 'Verificación Biométrica y 168 Horas (42 Épocas)', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_bioauthTitle', '生物特征验证与 168 小时 (42 周期)', 1794619673);
