INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_bioauthBadge', 'Verificación', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_bioauthBadge', '身份验证', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_bioauthSummary', 'Validatörlerin insan olduklarını ve aktifliklerini ispatladıkları periyodik biyometrik döngüdür.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_bioauthSummary', 'Periodic biometric cycle where validators prove uniqueness and ongoing liveness.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_bioauthSummary', 'Periodischer biometrischer Zyklus, in dem Validatoren ihre Einzigartigkeit und Aktivität beweisen.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_bioauthSummary', 'Периодический биометрический цикл, в котором валидаторы подтверждают подлинность и активность.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_bioauthSummary', 'Ciclo biométrico periódico en el que los validadores demuestran su actividad y humanidad.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_bioauthSummary', '验证者定期证明其唯一真实存在并保持在线的生物识别周期。', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_bioauthDetails', 'Her validatörün bioauth süresi 168 saat (yaklaşık 7 gün / 42 Epoch) olarak geri sayar. Bu süre dolmadan validatör yüz canlılık testini (liveness) yenilemelidir; aksi takdirde düğüm pasife düşer.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_bioauthDetails', 'Every validator has a 168-hour (approx 7 days / 42 epochs) countdown. Liveness must be renewed before expiration; otherwise the node becomes inactive.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_bioauthDetails', 'Jeder Validator hat einen 168-Stunden-Countdown. Die Lebendigkeitsprüfung muss vor Ablauf erneuert werden.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_bioauthDetails', 'У каждого валидатора идет обратный отсчет 168 часов. Проверку живости необходимо обновлять вовремя.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_bioauthDetails', 'Cada validador tiene una cuenta regresiva de 168 horas. La prueba de vida debe renovarse antes del vencimiento.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_bioauthDetails', '每个验证者的生物认证有效期为 168 小时（约 7 天 / 42 纪元）。必须在倒计时归零前重新完成 3D 活体检测，否则节点将被停用。', 1794619673);
