INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_feespotSummary', 'Ağ genelinde toplanan işlem ve transfer ücretlerinin biriktiği merkezi olmayan akıllı havuzdur.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_feespotSummary', 'Decentralized smart pool accumulating all transaction and transfer fees collected across the network.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_feespotSummary', 'Dezentraler Smart-Pool, in dem alle Transaktionsgebühren des Netzwerks gesammelt werden.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_feespotSummary', 'Децентрализованный пул, аккумулирующий все транзакционные комиссии сети.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_feespotSummary', 'Fondo inteligente descentralizado que acumula todas las tarifas de transacción de la red.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_feespotSummary', '汇集全网所有转账和交易手续费的去中心化智能资金池。', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_feespotDetails', 'FeesPot bakiyesi periyodik olarak tüm aktif biyometrik validatörlere eşit oranda paylaştırılır. Bu sayede validatörler işlem hacminden bağımsız olarak istikrarlı bir ödül akışı elde eder.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_feespotDetails', 'FeesPot balance is periodically distributed equally to all active biometric validators, providing a steady reward stream.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_feespotDetails', 'Das FeesPot-Guthaben wird periodisch zu gleichen Teilen an alle aktiven Validatoren verteilt.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_feespotDetails', 'Баланс FeesPot периодически распределяется поровну между всеми активными валидаторами.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_feespotDetails', 'El saldo de FeesPot se distribuye periódicamente en partes iguales a todos los validadores activos.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_feespotDetails', 'FeesPot 池中的资金会定期均等发放给所有活跃的人性验证节点，不受单个节点处理交易量影响。', 1794619673);
