INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_tokenomicsSummary', 'Humanode ağının enflasyonsuz, 400.000.000 HMND ile sınırlandırılmış sabit maksimum arz mimarisidir.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_tokenomicsSummary', 'Humanode network non-inflationary fixed maximum supply architecture capped at 400,000,000 HMND.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_tokenomicsSummary', 'Nicht-inflationäre feste maximale Angebotsarchitektur des Humanode-Netzwerks, begrenzt auf 400.000.000 HMND.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_tokenomicsSummary', 'Неинфляционная модель общего предложения Humanode с жестким лимитом в 400 000 000 HMND.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_tokenomicsSummary', 'Arquitectura de suministro máximo fijo sin inflación limitada a 400.000.000 HMND.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_tokenomicsSummary', 'Humanode 网络的零通胀模型，代币硬顶严格限制为 400,000,000 HMND。', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_tokenomicsDetails', 'Hiçbir koşulda 400M üzerinde token basılamaz. Ağda yakılan coinler (burn) toplam arzı deflasyonist olarak azaltır.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_tokenomicsDetails', 'Under no circumstances can more than 400M tokens be minted. Burned coins permanently reduce effective supply.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_tokenomicsDetails', 'Unter keinen Umständen können mehr als 400 Millionen Token geprägt werden. Verbrannte Coins reduzieren das Angebot dauerhaft.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_tokenomicsDetails', 'Ни при каких обстоятельствах не может быть выпущено более 400 млн токенов. Сжигание уменьшает предложение.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_tokenomicsDetails', 'Bajo ninguna circunstancia se pueden emitir más de 400M de tokens. Las monedas quemadas reducen el suministro permanentemente.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_tokenomicsDetails', '任何情况下都不会增发超过 4 亿枚代币。发送至销毁合约的代币将永久降低实际流通总量。', 1794619673);
