INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_subToEvmSummary', 'Native precompile system contract enabling instant bi-directional swaps between Substrate and EVM WeHMND.', 1794619673);
