INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_subToEvmSummary', 'Прекомпилированный системный контракт для мгновенного двустороннего обмена между Substrate и EVM WeHMND.', 1794619673);
