INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_subToEvmSummary', '在 Substrate 原生代币与 EVM WeHMND 之间实现原子级双向即时兑换的原生预编译系统合约。', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_subToEvmDetails', '0x0000000000000000000000000000000000000900 adresine gönderilen işlemler, harici bir üçüncü taraf köprüye ihtiyaç duymadan protokol düzeyinde atomik dönüşüm sağlar.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_subToEvmDetails', 'Transactions sent to 0x...900 achieve trustless, atomic protocol-level conversion without third-party bridges.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_subToEvmDetails', 'Transaktionen an 0x...900 bieten atomare Konvertierung auf Protokollebene ohne Drittanbieter.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_subToEvmDetails', 'Транзакции на 0x...900 обеспечивают атомарную конвертацию на уровне протокола без сторонних мостов.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_subToEvmDetails', 'Las transacciones enviadas a 0x...900 proporcionan conversión atómica a nivel de protocolo sin intermediarios.', 1794619673);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_subToEvmDetails', '发送至 0x...900 的交易直接在底层协议中完成原子兑换，无需依赖任何第三方中心化跨链桥。', 1794619673);
