INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_biomapperSummary', 'Humanode biyometrisini Ethereum, Arbitrum, Optimism gibi 25+ farklı EVM ağına güvenle bağlayan kimlik köprüsüdür.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_biomapperSummary', 'Identity bridge connecting Humanode biometrics to 25+ different EVM networks securely.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_biomapperSummary', 'Identitätsbrücke, die Humanode-Biometrie mit 25+ verschiedenen EVM-Netzwerken verbindet.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_biomapperSummary', 'Мост идентификации, связывающий биометрию Humanode с 25+ сетями EVM.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_biomapperSummary', 'Puente de identidad que conecta la biometría de Humanode con 25+ redes EVM de forma segura.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_biomapperSummary', '将 Humanode 生物认证安全桥接至以太坊、Arbitrum 等 25+ 条主流 EVM 网络的身份枢纽。', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_biomapperDetails', 'Kullanıcının biyometrik verisi hiçbir zaman ağa sızdırılmaz. Sıfır bilgi kanıtı ve kriptografik eşleme ile harici cüzdanın tekil bir insana ait olduğu doğrulanır.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_biomapperDetails', 'Biometric data is never leaked. Zero-knowledge proofs and cryptographic binding prove that an external wallet belongs to a unique human.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_biomapperDetails', 'Biometrische Daten werden niemals weitergegeben. Zero-Knowledge-Beweise verifizieren die Einzigartigkeit.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_biomapperDetails', 'Биометрические данные никогда не передаются в сеть. Доказательства с нулевым разглашением гарантируют уникальность.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_biomapperDetails', 'Los datos biométricos nunca se filtran. Las pruebas de conocimiento cero garantizan que la billetera pertenece a un humano único.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_biomapperDetails', '用户的生物特征永远不会泄露到网络中。通过零知识证明与加密绑定，证明外部链上钱包归属于独立的自然人，抵御女巫攻击。', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_dualLayerTitle', 'Substrate & EVM Çift Katmanı', 1794619709);
