INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_dualLayerSummary', 'Humanode hem Substrate tabanlı yerel konsensüs katmanını hem de Ethereum Sanal Makinesini (EVM) eşzamanlı çalıştırır.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_dualLayerSummary', 'Humanode simultaneously operates both a Substrate-based native consensus layer and the Ethereum Virtual Machine (EVM).', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_dualLayerSummary', 'Humanode betreibt gleichzeitig eine Substrate-basierte native Konsensschicht und die EVM.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_dualLayerSummary', 'Humanode одновременно поддерживает собственный уровень консенсуса Substrate и EVM.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_dualLayerSummary', 'Humanode opera simultáneamente una capa de consenso nativa de Substrate y la EVM.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_dualLayerSummary', 'Humanode 同时原生运行基于 Substrate 的底层共识层与以太坊虚拟机 (EVM)。', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'glossary_dualLayerDetails', 'Substrate katmanı biyometri, validatör oturumları ve hazine gibi temel sistem işlemlerini yönetirken; EVM katmanı standart Solidity akıllı sözleşmelerini yürütür.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'glossary_dualLayerDetails', 'Substrate manages biometrics, validator sessions, and treasury, while EVM executes standard Solidity contracts and ERC-20 tokens.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'glossary_dualLayerDetails', 'Substrate verwaltet Biometrie und Validatoren, während die EVM Solidity-Verträge ausführt.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'glossary_dualLayerDetails', 'Substrate управляет биометрией и валидаторами, а EVM исполняет смарт-контракты Solidity.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'glossary_dualLayerDetails', 'Substrate gestiona la biometría y validadores, mientras que la EVM ejecuta contratos inteligentes de Solidity.', 1794619709);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'glossary_dualLayerDetails', 'Substrate 层专门调度生物认证、验证者纪元与金库 extrinsics；EVM 层则运行标准的 Solidity 智能合约与 ERC-20 生态代币。', 1794619709);
