INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('tr', 'tokenomics_fixedSupplyDesc', 'Hiçbir koşulda 400.000.000 HMND üzerinde token basılamaz. Yakma kontratında yok edilen coinler toplam arzı deflasyonist olarak azaltır.', NULL);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('en', 'tokenomics_fixedSupplyDesc', 'Under no circumstances can more than 400,000,000 HMND be minted. Coins burned in the burn contract permanently reduce the total supply.', NULL);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('de', 'tokenomics_fixedSupplyDesc', 'Unter keinen Umständen können mehr als 400.000.000 HMND geprägt werden. Im Burn-Vertrag vernichtete Coins reduzieren das Gesamtangebot dauerhaft.', NULL);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('ru', 'tokenomics_fixedSupplyDesc', 'Ни при каких обстоятельствах не может быть выпущено более 400 000 000 HMND. Монеты, сожженные в смарт-контракте, навсегда сокращают общее предложение.', NULL);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('es', 'tokenomics_fixedSupplyDesc', 'Bajo ninguna circunstancia se pueden emitir más de 400.000.000 HMND. Las monedas quemadas en el contrato reducen permanentemente el suministro total.', NULL);
INSERT OR REPLACE INTO app_translations (lang_code, translation_key, translation_value, updated_at) VALUES ('zh', 'tokenomics_fixedSupplyDesc', '在任何情况下都不会铸造超过 4 亿枚 HMND。在销毁合约中销毁的代币将永久减少总供应量。', NULL);
