-- Table: query_sandbox_presets (6 records)
INSERT OR REPLACE INTO query_sandbox_presets (id, title_key, description_key, sql_query, display_order) VALUES ('top-gas-burners', 'preset_top_burners_title', 'preset_top_burners_desc', 'SELECT from_address as wallet, COUNT(*) as tx_count, ROUND(SUM(fee_hmnd), 4) as total_fee_hmnd FROM transactions GROUP BY from_address ORDER BY total_fee_hmnd DESC LIMIT 10;', 1);
INSERT OR REPLACE INTO query_sandbox_presets (id, title_key, description_key, sql_query, display_order) VALUES ('monthly-growth', 'preset_monthly_growth_title', 'preset_monthly_growth_desc', 'SELECT strftime(''%Y-%m'', datetime(timestamp, ''unixepoch'')) as month, COUNT(*) as evm_tx_count, ROUND(SUM(fee_hmnd), 2) as fees_hmnd FROM transactions WHERE timestamp > 0 GROUP BY month ORDER BY month DESC LIMIT 12;', 2);
INSERT OR REPLACE INTO query_sandbox_presets (id, title_key, description_key, sql_query, display_order) VALUES ('bridge-whale-volume', 'preset_bridge_volume_title', 'preset_bridge_volume_desc', 'SELECT substrate_address, evm_address, ROUND(total_swapped_hmnd, 2) as swapped_hmnd, swap_count FROM cross_layer_links ORDER BY total_swapped_hmnd DESC LIMIT 10;', 3);
INSERT OR REPLACE INTO query_sandbox_presets (id, title_key, description_key, sql_query, display_order) VALUES ('active-validators-30d', 'preset_active_validators_title', 'preset_active_validators_desc', 'SELECT signer as validator_address, COUNT(*) as heartbeat_and_auth_count, MAX(timestamp) as last_seen FROM substrate_extrinsics WHERE pallet IN (''imOnline'', ''bioauth'') GROUP BY signer ORDER BY heartbeat_and_auth_count DESC LIMIT 20;', 4);
INSERT OR REPLACE INTO query_sandbox_presets (id, title_key, description_key, sql_query, display_order) VALUES ('highest-value-transfers', 'preset_highest_transfers_title', 'preset_highest_transfers_desc', 'SELECT hash, from_address, to_address, ROUND(value_hmnd, 2) as value_hmnd, datetime(timestamp, ''unixepoch'') as date_utc FROM transactions WHERE value_hmnd > 0 ORDER BY value_hmnd DESC LIMIT 20;', 5);
INSERT OR REPLACE INTO query_sandbox_presets (id, title_key, description_key, sql_query, display_order) VALUES ('token-distribution-summary', 'preset_token_dist_title', 'preset_token_dist_desc', 'SELECT token_symbol, COUNT(*) as transfer_count, COUNT(DISTINCT to_address) as unique_holders, ROUND(SUM(amount), 2) as total_volume FROM token_transfers GROUP BY token_symbol ORDER BY transfer_count DESC LIMIT 15;', 6);


